import { describe, expect, test } from 'claude-code/testing'

import Detect from '../../../hooks/deps/detect'

describe('yarn-lock-versions-of', () => {
  const CLASSIC = [
    '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.',
    '# yarn lockfile v1',
    '',
    '',
    '"@babel/core@^7.0.0", "@babel/core@^7.23.0":',
    '  version "7.24.0"',
    '  resolved "https://registry.yarnpkg.com/@babel/core/-/core-7.24.0.tgz"',
    '',
    'semver@^6.3.0:',
    '  version "6.3.1"',
    '',
    'semver@^7.5.0:',
    '  version "7.6.3"',
    '',
    'chalk@^4.0.0:',
    '  version "4.1.2"',
    '',
  ].join('\n')

  const BERRY = [
    '__metadata:',
    '  version: 8',
    '',
    '"react@npm:^18.3.0":',
    '  version: 18.3.1',
    '  resolution: "react@npm:18.3.1"',
    '',
  ].join('\n')

  test('classic: the descriptor that matches the range answers', () => {
    const lookup = Detect.yarnLockVersionsOf(CLASSIC)

    expect(lookup('@babel/core', '^7.23.0')).toBe('7.24.0')
    expect(lookup('semver', '^6.3.0')).toBe('6.3.1')
    expect(lookup('semver', '^7.5.0')).toBe('7.6.3')
  })

  test('berry: descriptors carry the npm: protocol', () => {
    expect(Detect.yarnLockVersionsOf(BERRY)('react', '^18.3.0')).toBe('18.3.1')
  })

  test('no descriptor for the range: the only version locked for the name, else none', () => {
    const lookup = Detect.yarnLockVersionsOf(CLASSIC)

    expect(lookup('chalk', '^4.1.0')).toBe('4.1.2')
    expect(lookup('semver', '^5.0.0')).toBeUndefined()
    expect(lookup('missing', '^1.0.0')).toBeUndefined()
  })

  test('a file with no entries throws', () => {
    expect(() => Detect.yarnLockVersionsOf('# yarn lockfile v1\n')).toThrow('no yarn.lock entries')
  })
})
